     9	import java.math.BigDecimal;
    10	import java.text.NumberFormat;
    11	import java.util.Locale;
    12	import java.util.function.Consumer;
    13	
    14	public class FinanceNotificationListener implements Consumer<Event> {
    15	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    16	    private static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
    17	
    18	    private final MessageService messageService;
    19	
    20	    public FinanceNotificationListener(MessageService messageService) {
    21	        this.messageService = messageService;
    22	    }
    23	
    24	    @Override
    25	    public void accept(Event event) {
    26	        if (event instanceof ReservationConfirmedEvent confirmedEvent) {
    27	            sendPaymentNotification(confirmedEvent.reservation());
    28	        } else if (event instanceof ReservationCancelledEvent cancelledEvent) {
    29	            if (cancelledEvent.wasConfirmed() &&
    30	                cancelledEvent.reservation().getRefund().compareTo(BigDecimal.ZERO) > 0) {
    31	                sendRefundNotification(cancelledEvent.reservation());
    32	            }
    33	        }
    34	    }
    35	
    36	    private void sendPaymentNotification(Reservation reservation) {
    37	        String body = String.format(
    38	            "Valor pago: %s",
    39	            CURRENCY_FORMAT.format(reservation.getAmountPaid())
    40	        );
    41	
    42	        messageService.sendEmail(
    43	            FINANCE_EMAIL,
    44	            String.format("Pagamento recebido - reserva %d", reservation.getId()),
    45	            body
    46	        );
    47	    }
    48	
    49	    private void sendRefundNotification(Reservation reservation) {
    50	        String body = String.format(
    51	            "Valor a devolver: %s",
    52	            CURRENCY_FORMAT.format(reservation.getRefund())
    53	        );
    54	
    55	        messageService.sendEmail(
    56	            FINANCE_EMAIL,
    57	            String.format("Reembolso - reserva %d", reservation.getId()),
    58	            body
    59	        );
    60	    }
    61	}
