     8	import java.math.BigDecimal;
     9	import java.text.NumberFormat;
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeFormatter;
    12	import java.util.Locale;
    13	import java.util.function.Consumer;
    14	
    15	public class GuestNotificationListener implements Consumer<Event> {
    16	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    17	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    18	
    19	    private final MessageService messageService;
    20	
    21	    public GuestNotificationListener(MessageService messageService) {
    22	        this.messageService = messageService;
    23	    }
    24	
    25	    @Override
    26	    public void accept(Event event) {
    27	        if (event instanceof ReservationConfirmedEvent confirmedEvent) {
    28	            sendConfirmationEmail(confirmedEvent.reservation());
    29	        }
    30	    }
    31	
    32	    private void sendConfirmationEmail(Reservation reservation) {
    33	        String voucher = generateVoucher(reservation);
    34	        String body = String.format("""
    35	            Olá, %s!
    36	
    37	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    38	
    39	            %s
    40	
    41	            A entrada é a partir das 14h, e a saída, até as 12h.
    42	            Até breve!""", reservation.getGuestName(), voucher);
    43	
    44	        messageService.sendEmail(
    45	            reservation.getGuestEmail(),
    46	            "Reserva confirmada - Pousada Maré Alta",
    47	            body
    48	        );
    49	    }
    50	
    51	    private String generateVoucher(Reservation reservation) {
    52	        StringBuilder voucher = new StringBuilder();
    53	        voucher.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
    54	        voucher.append(String.format("Hóspede: %s (CPF %s)%n",
    55	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
    56	        voucher.append(String.format("Quarto: %s (%s)%n",
    57	            reservation.getRoomNumber(), getRoomTypeName(reservation.getRoomNumber())));
    58	        voucher.append(String.format("Entrada: %s | Saída: %s | %s%n",
    59	            formatDate(reservation.getCheckIn()),
    60	            formatDate(reservation.getCheckOut()),
    61	            formatNights(reservation.getNights())));
    62	        voucher.append(String.format("Diárias: %s%n", formatMoney(reservation.getSubtotal())));
    63	
    64	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    65	            voucher.append(String.format("Desconto: %s%n", formatMoney(reservation.getDiscount())));
    66	        }
    67	
    68	        voucher.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
    69	
    70	        return voucher.toString();
    71	    }
    72	
    73	    private String getRoomTypeName(String roomNumber) {
    74	        return switch (roomNumber) {
    75	            case "101", "102" -> "STANDARD";
    76	            case "201", "202" -> "DELUXE";
    77	            case "301" -> "SUITE";
    78	            default -> "";
    79	        };
    80	    }
    81	
    82	    private String formatCpf(String cpf) {
    83	        if (cpf.length() == 11) {
    84	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    85	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    86	        }
    87	        return cpf;
    88	    }
    89	
    90	    private String formatDate(LocalDate date) {
    91	        return date.format(DATE_FORMATTER);
    92	    }
    93	
    94	    private String formatNights(int nights) {
    95	        return nights == 1 ? "1 diária" : nights + " diárias";
    96	    }
    97	
    98	    private String formatMoney(BigDecimal amount) {
    99	        return CURRENCY_FORMAT.format(amount);
   100	    }
   101	}
