     1	package com.pousadamarealta.domain.service;
     2	
     3	import com.pousadamarealta.domain.event.ReservationCancelledEvent;
     4	import com.pousadamarealta.domain.event.ReservationConfirmedEvent;
     5	import com.pousadamarealta.domain.model.*;
     6	import com.pousadamarealta.domain.repository.ReservationRepository;
     7	
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.time.temporal.ChronoUnit;
    11	import java.util.Optional;
    12	
    13	public class ReservationService {
    14	    private final ReservationRepository reservationRepository;
    15	    private final PricingService pricingService;
    16	    private final EventBus eventBus;
    17	
    18	    public ReservationService(ReservationRepository reservationRepository,
    19	                             PricingService pricingService,
    20	                             EventBus eventBus) {
    21	        this.reservationRepository = reservationRepository;
    22	        this.pricingService = pricingService;
    23	        this.eventBus = eventBus;
    24	    }
    25	
    26	    public Reservation createReservation(String roomNumber, Room room, String guestName,
    27	                                        String guestEmail, String guestCpf,
    28	                                        LocalDate checkIn, LocalDate checkOut,
    29	                                        int guests, RatePlan ratePlan) {
    30	        Long id = reservationRepository.getNextId();
    31	
    32	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    33	
    34	        BigDecimal subtotal = calculateSubtotal(room.getNightlyRate(), checkIn, nights);
    35	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    36	        BigDecimal total = subtotal.subtract(discount);
    37	
    38	        Reservation reservation = new Reservation(
    39	            id, roomNumber, guestName, guestEmail, guestCpf,
    40	            checkIn, checkOut, guests, ratePlan, nights,
    41	            subtotal, discount, total
    42	        );
    43	
    44	        return reservationRepository.save(reservation);
    45	    }
    46	
    47	    public Reservation confirmReservation(Long id) {
    48	        Reservation reservation = reservationRepository.findById(id)
    49	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
    50	
    51	        if (!reservation.canConfirm()) {
    52	            throw new IllegalStateException("Cannot confirm reservation in current status");
    53	        }
    54	
    55	        reservation.confirm();
    56	        reservationRepository.save(reservation);
    57	
    58	        eventBus.publish(new ReservationConfirmedEvent(reservation));
    59	
    60	        return reservation;
    61	    }
    62	
    63	    public Reservation cancelReservation(Long id) {
    64	        Reservation reservation = reservationRepository.findById(id)
    65	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
    66	
    67	        if (!reservation.canCancel()) {
    68	            throw new IllegalStateException("Cannot cancel reservation in current status");
    69	        }
    70	
    71	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
    72	
    73	        reservation.cancel();
    74	        reservationRepository.save(reservation);
    75	
    76	        eventBus.publish(new ReservationCancelledEvent(reservation, wasConfirmed));
    77	
    78	        return reservation;
    79	    }
    80	
    81	    public Reservation checkInReservation(Long id) {
    82	        Reservation reservation = reservationRepository.findById(id)
    83	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
    84	
    85	        if (!reservation.canCheckIn()) {
    86	            throw new IllegalStateException("Cannot check-in reservation in current status");
    87	        }
    88	
    89	        reservation.checkIn();
    90	        return reservationRepository.save(reservation);
    91	    }
    92	
    93	    public Reservation checkOutReservation(Long id) {
    94	        Reservation reservation = reservationRepository.findById(id)
    95	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
    96	
    97	        if (!reservation.canCheckOut()) {
    98	            throw new IllegalStateException("Cannot check-out reservation in current status");
    99	        }
   100	
   101	        reservation.checkOut();
   102	        return reservationRepository.save(reservation);
   103	    }
   104	
   105	    public Optional<Reservation> getReservation(Long id) {
   106	        return reservationRepository.findById(id);
   107	    }
   108	
   109	    public boolean hasRoomConflict(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
   110	        return reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null);
   111	    }
   112	
   113	    private BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, int nights) {
   114	        BigDecimal subtotal = BigDecimal.ZERO;
   115	
   116	        for (int i = 0; i < nights; i++) {
   117	            LocalDate night = checkIn.plusDays(i);
   118	            BigDecimal nightPrice = pricingService.calculateNightPrice(baseRate, night);
   119	            subtotal = subtotal.add(nightPrice);
   120	        }
   121	
   122	        return subtotal.setScale(2, java.math.RoundingMode.HALF_EVEN);
   123	    }
   124	}
