119	public class ReservationController {
120	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
121	
122	    private final ReservationService reservationService;
123	    private final RoomService roomService;
124	
125	    public ReservationController(ReservationService reservationService, RoomService roomService) {
126	        this.reservationService = reservationService;
127	        this.roomService = roomService;
128	    }
129	
130	    public void createReservation(Context ctx) {
131	        try {
132	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
133	
134	            if (request.roomNumber() == null || request.guestName() == null ||
135	                request.guestEmail() == null || request.guestCpf() == null ||
136	                request.checkIn() == null || request.checkOut() == null || request.ratePlan() == null) {
137	                ctx.status(400).json(new ErrorResponse(
138	                    ErrorCode.INVALID_REQUEST.name(),
139	                    "Missing required fields"
140	                ));
141	                return;
142	            }
143	
144	            LocalDate checkIn;
145	            LocalDate checkOut;
146	            try {
147	                checkIn = LocalDate.parse(request.checkIn(), DATE_FORMATTER);
148	                checkOut = LocalDate.parse(request.checkOut(), DATE_FORMATTER);
149	            } catch (DateTimeParseException e) {
150	                ctx.status(400).json(new ErrorResponse(
151	                    ErrorCode.INVALID_REQUEST.name(),
152	                    "Invalid date format"
153	                ));
154	                return;
155	            }
156	
157	            if (!checkOut.isAfter(checkIn)) {
158	                ctx.status(400).json(new ErrorResponse(
159	                    ErrorCode.INVALID_REQUEST.name(),
160	                    "Check-out must be after check-in"
161	                ));
162	                return;
163	            }
164	
165	            if (request.guests() < 1) {
166	                ctx.status(400).json(new ErrorResponse(
167	                    ErrorCode.INVALID_REQUEST.name(),
168	                    "At least one guest is required"
169	                ));
170	                return;
171	            }
172	
173	            Room room = roomService.getRoomByNumber(request.roomNumber()).orElse(null);
174	            if (room == null) {
175	                ctx.status(404).json(new ErrorResponse(
176	                    ErrorCode.ROOM_NOT_FOUND.name(),
177	                    "Room not found"
178	                ));
179	                return;
180	            }
181	
182	            if (request.guests() > room.getCapacity()) {
183	                ctx.status(422).json(new ErrorResponse(
184	                    ErrorCode.CAPACITY_EXCEEDED.name(),
185	                    "Number of guests exceeds room capacity"
186	                ));
187	                return;
188	            }
189	
190	            if (reservationService.hasRoomConflict(request.roomNumber(), checkIn, checkOut)) {
191	                ctx.status(409).json(new ErrorResponse(
192	                    ErrorCode.ROOM_UNAVAILABLE.name(),
193	                    "Room is not available for the selected dates"
194	                ));
195	                return;
196	            }
197	
198	            RatePlan ratePlan;
199	            try {
200	                ratePlan = RatePlan.valueOf(request.ratePlan());
201	            } catch (IllegalArgumentException e) {
202	                ctx.status(400).json(new ErrorResponse(
203	                    ErrorCode.INVALID_REQUEST.name(),
204	                    "Invalid rate plan"
205	                ));
206	                return;
207	            }
208	
209	            Reservation reservation = reservationService.createReservation(
210	                request.roomNumber(), room, request.guestName(), request.guestEmail(),
211	                request.guestCpf(), checkIn, checkOut, request.guests(), ratePlan
212	            );
213	
214	            ctx.status(201).json(toDTO(reservation));
215	
216	        } catch (Exception e) {
217	            ctx.status(400).json(new ErrorResponse(
218	                ErrorCode.INVALID_REQUEST.name(),
219	                "Invalid request body"
220	            ));
221	        }
222	    }
