464	import java.math.BigDecimal;
465	import java.math.RoundingMode;
466	import java.time.LocalDate;
467	
468	public class PricingService {
469	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
470	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
471	
472	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
473	        if (isHighSeason(night)) {
474	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
475	        }
476	        return baseRate;
477	    }
478	
479	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
480	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
481	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
482	        }
483	        return BigDecimal.ZERO;
484	    }
485	
486	    private boolean isHighSeason(LocalDate date) {
487	        int month = date.getMonthValue();
488	        int day = date.getDayOfMonth();
489	
490	        if (month == 12 && day >= 15) {
491	            return true;
492	        }
493	
494	        if (month == 1 || month == 2) {
495	            return true;
496	        }
497	
498	        if (month == 7) {
499	            return true;
500	        }
501	
502	        return false;
503	    }
504	
505	    private BigDecimal round(BigDecimal value) {
506	        return value.setScale(2, RoundingMode.HALF_EVEN);
507	    }
508	}
