   279	            .filter(r -> !r.getId().equals(excludeReservationId))
   280	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   281	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   282	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
